     8	import java.time.LocalDate;
     9	
    10	public interface RatePlanStrategy {
    11	
    12	    void validate(LocalDate checkIn, LocalDate checkOut, int nights, String companyCode);
    13	
    14	    PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights);
    15	
    16	    BigDecimal calculateRefund(BigDecimal amountPaid);
    17	
    18	    default boolean isHighSeason(LocalDate date) {
    19	        int month = date.getMonthValue();
    20	        int day = date.getDayOfMonth();
    21	
    22	        if (month == 7) {
    23	            return true;
    24	        }
    25	
    26	        if (month == 12 && day >= 15) {
    27	            return true;
    28	        }
    29	
    30	        if (month == 1 || month == 2) {
    31	            return true;
    32	        }
    33	
    34	        return false;
    35	    }
    36	
    37	    default BigDecimal calculateNightRate(RoomType roomType, LocalDate date) {
    38	        BigDecimal baseRate = roomType.getNightlyRate();
    39	        if (isHighSeason(date)) {
    40	            return round(baseRate.multiply(new BigDecimal("1.20")));
    41	        }
    42	        return baseRate;
    43	    }
    44	
    45	    default BigDecimal round(BigDecimal value) {
    46	        return value.setScale(2, RoundingMode.HALF_EVEN);
    47	    }
    48	}
