     7	import java.math.BigDecimal;
     8	import java.time.DayOfWeek;
     9	import java.time.LocalDate;
    10	import java.util.Map;
    11	
    12	public class WeekendPackageRatePlan implements RatePlanStrategy {
    13	
    14	    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    15	        RoomType.STANDARD, new BigDecimal("520.00"),
    16	        RoomType.DELUXE, new BigDecimal("820.00"),
    17	        RoomType.SUITE, new BigDecimal("1200.00")
    18	    );
    19	
    20	    @Override
    21	    public void validate(LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    22	        if (nights != 2) {
    23	            throw new InvalidRequestException("O pacote de fim de semana exige exatamente 2 noites");
    24	        }
    25	
    26	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    27	            throw new InvalidRequestException("O pacote de fim de semana deve começar na sexta-feira");
    28	        }
    29	
    30	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    31	            throw new InvalidRequestException("O pacote de fim de semana deve terminar no domingo");
    32	        }
    33	    }
    34	
    35	    @Override
    36	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    37	        BigDecimal packagePrice = PACKAGE_PRICES.get(room.getType());
    38	        return new PricingResult(packagePrice, BigDecimal.ZERO, packagePrice);
    39	    }
    40	
    41	    @Override
    42	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    43	        return round(amountPaid.multiply(new BigDecimal("0.50")));
    44	    }
    45	}
