=== service/ReservationService.java
     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.exception.*;
     4	import com.pousadamarealta.model.*;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.temporal.ChronoUnit;
     9	import java.util.*;
    10	import java.util.concurrent.atomic.AtomicLong;
    11	
    12	public class ReservationService {
    13	    private final Map<Long, Reservation> reservations = new HashMap<>();
    14	    private final AtomicLong nextId = new AtomicLong(1);
    15	    private final RoomService roomService;
    16	    private final MessageService messageService;
    17	    private final Map<RatePlan, RatePlanStrategy> strategies = new EnumMap<>(RatePlan.class);
    18	
    19	    public ReservationService(RoomService roomService, MessageService messageService) {
    20	        this.roomService = roomService;
    21	        this.messageService = messageService;
    22	
    23	        strategies.put(RatePlan.STANDARD, new StandardRatePlan());
    24	        strategies.put(RatePlan.NON_REFUNDABLE, new NonRefundableRatePlan());
    25	        strategies.put(RatePlan.CORPORATE, new CorporateRatePlan());
    26	        strategies.put(RatePlan.WEEKEND_PACKAGE, new WeekendPackageRatePlan());
    27	        strategies.put(RatePlan.LONG_STAY, new LongStayRatePlan());
    28	    }
    29	
    30	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    31	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    32	                                        int guests, RatePlan ratePlan, String companyCode) {
    33	
    34	        Room room = roomService.getRoom(roomNumber);
    35	
    36	        if (guests < 1) {
    37	            throw new InvalidRequestException("O número de hóspedes deve ser no mínimo 1");
    38	        }
    39	
    40	        if (guests > room.getCapacity()) {
    41	            throw new CapacityExceededException();
    42	        }
    43	
    44	        if (!checkOut.isAfter(checkIn)) {
    45	            throw new InvalidRequestException("A data de saída deve ser posterior à data de entrada");
    46	        }
    47	
    48	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    49	
    50	        RatePlanStrategy strategy = strategies.get(ratePlan);
    51	        strategy.validate(checkIn, checkOut, nights, companyCode);
    52	
    53	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    54	            throw new RoomUnavailableException();
    55	        }
    56	
    57	        PricingResult pricing;
    58	        if (ratePlan == RatePlan.CORPORATE) {
    59	            pricing = ((CorporateRatePlan) strategy).calculatePrice(room, checkIn, checkOut, nights, companyCode);
    60	        } else {
    61	            pricing = strategy.calculatePrice(room, checkIn, checkOut, nights);
    62	        }
    63	
    64	        Reservation reservation = new Reservation(
    65	            nextId.getAndIncrement(),
    66	            roomNumber,
    67	            guestName,
    68	            guestEmail,
    69	            guestCpf,
    70	            checkIn,
    71	            checkOut,
    72	            guests,
    73	            ratePlan,
    74	            companyCode,
    75	            nights,
    76	            pricing.subtotal(),
    77	            pricing.discount(),
    78	            pricing.total()
    79	        );
    80	
    81	        reservations.put(reservation.getId(), reservation);
    82	        return reservation;
    83	    }
    84	
    85	    public Reservation getReservation(long id) {
    86	        Reservation reservation = reservations.get(id);
    87	        if (reservation == null) {
    88	            throw new ReservationNotFoundException();
    89	        }
    90	        return reservation;
    91	    }
    92	
    93	    public Reservation confirmReservation(long id) {
    94	        Reservation reservation = getReservation(id);
    95	
    96	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    97	            throw new OperationNotAllowedException("Apenas reservas pendentes podem ser confirmadas");
    98	        }
    99	
   100	        reservation.setStatus(ReservationStatus.CONFIRMED);
   101	        reservation.setAmountPaid(reservation.getTotal());
   102	
   103	        sendConfirmationEmail(reservation);
   104	
   105	        return reservation;
   106	    }
   107	
   108	    public Reservation cancelReservation(long id) {
   109	        Reservation reservation = getReservation(id);
   110	
   111	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   112	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   113	            throw new OperationNotAllowedException("Apenas reservas pendentes ou confirmadas podem ser canceladas");
   114	        }
   115	
   116	        RatePlanStrategy strategy = strategies.get(reservation.getRatePlan());
   117	        BigDecimal refundAmount = strategy.calculateRefund(reservation.getAmountPaid());
   118	
   119	        reservation.setStatus(ReservationStatus.CANCELLED);
   120	        reservation.setRefund(refundAmount);
   121	
   122	        return reservation;
   123	    }
   124	
   125	    public Reservation checkIn(long id) {
   126	        Reservation reservation = getReservation(id);
   127	
   128	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   129	            throw new OperationNotAllowedException("Apenas reservas confirmadas podem fazer check-in");
   130	        }
   131	
   132	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   133	        return reservation;
   134	    }
   135	
   136	    public Reservation checkOut(long id) {
   137	        Reservation reservation = getReservation(id);
   138	
   139	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   140	            throw new OperationNotAllowedException("Apenas reservas com check-in podem fazer check-out");
   141	        }
   142	
   143	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   144	        return reservation;
   145	    }
   146	
   147	    public List<Reservation> getAllReservations() {
   148	        return new ArrayList<>(reservations.values());
   149	    }
   150	
   151	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   152	        return reservations.values().stream()
   153	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   154	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   155	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   156	    }
   157	
   158	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   159	        return start1.isBefore(end2) && start2.isBefore(end1);
   160	    }
   161	
   162	    private void sendConfirmationEmail(Reservation reservation) {
   163	        Room room = roomService.getRoom(reservation.getRoomNumber());
   164	        String receipt = formatReceipt(reservation, room);
   165	
   166	        String subject = "Reserva confirmada - Pousada Maré Alta";
   167	        String body = String.format(
   168	            "Olá, %s!\n\n" +
   169	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   170	            "%s\n\n" +
   171	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   172	            "Até breve!",
   173	            reservation.getGuestName(),
   174	            receipt
   175	        );
   176	
   177	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
   178	    }
   179	
   180	    private String formatReceipt(Reservation reservation, Room room) {
   181	        StringBuilder receipt = new StringBuilder();
   182	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   183	        receipt.append("Hóspede: ").append(reservation.getGuestName())
   184	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   185	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
   186	               .append(" (").append(room.getType()).append(")\n");
   187	        receipt.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
   188	               .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
   189	               .append(" | ").append(reservation.getNights())
   190	               .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
   191	        receipt.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
   192	
   193	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   194	            receipt.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
   195	        }
   196	
   197	        receipt.append("Total: ").append(formatMoney(reservation.getTotal()));
   198	
   199	        return receipt.toString();
   200	    }
   201	
   202	    public String getReceiptText(Reservation reservation) {
   203	        Room room = roomService.getRoom(reservation.getRoomNumber());
   204	        return formatReceipt(reservation, room);
   205	    }
   206	
   207	    private String formatMoney(BigDecimal value) {
   208	        return String.format("R$ %,.2f", value).replace(",", ".");
   209	    }
   210	
   211	    private String formatDate(LocalDate date) {
   212	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   213	    }
   214	
   215	    private String formatCpf(String cpf) {
   216	        if (cpf.length() == 11) {
   217	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
   218	                   cpf.substring(6, 9) + "-" + cpf.substring(9, 11);
   219	        }
   220	        return cpf;
   221	    }
   222	}

