    30	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    31	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    32	                                        int guests, RatePlan ratePlan, String companyCode) {
    33	
    34	        Room room = roomService.getRoom(roomNumber);
    35	
    36	        if (guests < 1) {
    37	            throw new InvalidRequestException("O número de hóspedes deve ser no mínimo 1");
    38	        }
    39	
    40	        if (guests > room.getCapacity()) {
    41	            throw new CapacityExceededException();
    42	        }
    43	
    44	        if (!checkOut.isAfter(checkIn)) {
    45	            throw new InvalidRequestException("A data de saída deve ser posterior à data de entrada");
    46	        }
    47	
    48	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    49	
    50	        RatePlanStrategy strategy = strategies.get(ratePlan);
    51	        strategy.validate(checkIn, checkOut, nights, companyCode);
    52	
    53	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    54	            throw new RoomUnavailableException();
    55	        }
    56	
    57	        PricingResult pricing;
    58	        if (ratePlan == RatePlan.CORPORATE) {
    59	            pricing = ((CorporateRatePlan) strategy).calculatePrice(room, checkIn, checkOut, nights, companyCode);
    60	        } else {
    61	            pricing = strategy.calculatePrice(room, checkIn, checkOut, nights);
    62	        }
    63	
    64	        Reservation reservation = new Reservation(
    65	            nextId.getAndIncrement(),
    66	            roomNumber,
    67	            guestName,
    68	            guestEmail,
    69	            guestCpf,
    70	            checkIn,
    71	            checkOut,
    72	            guests,
    73	            ratePlan,
    74	            companyCode,
    75	            nights,
    76	            pricing.subtotal(),
    77	            pricing.discount(),
    78	            pricing.total()
    79	        );
    80	
    81	        reservations.put(reservation.getId(), reservation);
    82	        return reservation;
    83	    }
