   151	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   152	        return reservations.values().stream()
   153	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   154	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   155	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   156	    }
