   162	    private void sendConfirmationEmail(Reservation reservation) {
   163	        Room room = roomService.getRoom(reservation.getRoomNumber());
   164	        String receipt = formatReceipt(reservation, room);
   165	
   166	        String subject = "Reserva confirmada - Pousada Maré Alta";
   167	        String body = String.format(
