   170	            "%s\n\n" +
   171	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   172	            "Até breve!",
   173	            reservation.getGuestName(),
   174	            receipt
   175	        );
   176	
   177	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
