235	   235	public class ReportService {
236	   236	    private final ReservationService reservationService;
237	   237	    private final RoomService roomService;
238	   238	
239	   239	    public ReportService(ReservationService reservationService, RoomService roomService) {
240	   240	        this.reservationService = reservationService;
241	   241	        this.roomService = roomService;
242	   242	    }
