244	   244	    public String generateOccupancyReport(LocalDate date) {
245	   245	        StringBuilder csv = new StringBuilder();
246	   246	        csv.append("room,type,reservation,check_in,check_out\n");
247	   247	
248	   248	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
249	   249	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
250	   250	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
251	   251	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
252	   252	            .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
253	   253	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
254	   254	            .collect(Collectors.toList());
255	   255	
256	   256	        for (Reservation reservation : occupiedReservations) {
257	   257	            Room room = roomService.getRoom(reservation.getRoomNumber());
258	   258	            csv.append(reservation.getRoomNumber()).append(",");
259	   259	            csv.append(room.getType()).append(",");
260	   260	            csv.append(reservation.getId()).append(",");
261	   261	            csv.append(formatDateForCsv(reservation.getCheckIn())).append(",");
262	   262	            csv.append(formatDateForCsv(reservation.getCheckOut())).append("\n");
263	   263	        }
264	   264	
265	   265	        int totalRooms = roomService.getAllRooms().size();
266	   266	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms);
267	   267	
268	   268	        return csv.toString();
269	   269	    }
270	   270	
271	   271	    public String generateRevenueReport(YearMonth month) {
272	   272	        StringBuilder csv = new StringBuilder();
273	   273	        csv.append("reservation,room,check_in,check_out,status,amount\n");
274	   274	
275	   275	        LocalDate monthStart = month.atDay(1);
276	   276	        LocalDate monthEnd = month.atEndOfMonth();
277	   277	
278	   278	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
279	   279	            .filter(r -> !r.getCheckIn().isBefore(monthStart) && !r.getCheckIn().isAfter(monthEnd))
280	   280	            .filter(r -> {
281	   281	                BigDecimal netAmount = r.getAmountPaid().subtract(
282	   282	                    r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO
283	   283	                );
284	   284	                return netAmount.compareTo(BigDecimal.ZERO) > 0;
285	   285	            })
286	   286	            .sorted(Comparator.comparing(Reservation::getCheckIn)
287	   287	                             .thenComparing(Reservation::getId))
288	   288	            .collect(Collectors.toList());
289	   289	
290	   290	        BigDecimal total = BigDecimal.ZERO;
291	   291	
292	   292	        for (Reservation reservation : monthReservations) {
293	   293	            BigDecimal netAmount = reservation.getAmountPaid().subtract(
294	   294	                reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO
295	   295	            );
296	   296	
297	   297	            csv.append(reservation.getId()).append(",");
298	   298	            csv.append(reservation.getRoomNumber()).append(",");
299	   299	            csv.append(formatDateForCsv(reservation.getCheckIn())).append(",");
300	   300	            csv.append(formatDateForCsv(reservation.getCheckOut())).append(",");
301	   301	            csv.append(reservation.getStatus()).append(",");
302	   302	            csv.append(formatMoneyForCsv(netAmount)).append("\n");
303	   303	
304	   304	            total = total.add(netAmount);
305	   305	        }
306	   306	
307	   307	        csv.append("total,").append(formatMoneyForCsv(total));
308	   308	
309	   309	        return csv.toString();
310	   310	    }
311	   311	
312	   312	    private String formatDateForCsv(LocalDate date) {
313	   313	        return date.format(DateTimeFormatter.ISO_LOCAL_DATE);
314	   314	    }
315	   315	
316	   316	    private String formatMoneyForCsv(BigDecimal value) {
317	   317	        return String.format("%.2f", value);
318	   318	    }
319	   319	}
