223	import com.pousadamarealta.model.Reservation;
224	import com.pousadamarealta.model.ReservationStatus;
225	import com.pousadamarealta.model.Room;
226	
227	import java.math.BigDecimal;
228	import java.time.LocalDate;
229	import java.time.YearMonth;
230	import java.time.format.DateTimeFormatter;
231	import java.util.Comparator;
232	import java.util.List;
233	import java.util.stream.Collectors;
234	
235	public class ReportService {
236	    private final ReservationService reservationService;
237	    private final RoomService roomService;
238	
239	    public ReportService(ReservationService reservationService, RoomService roomService) {
240	        this.reservationService = reservationService;
241	        this.roomService = roomService;
242	    }
243	
244	    public String generateOccupancyReport(LocalDate date) {
245	        StringBuilder csv = new StringBuilder();
246	        csv.append("room,type,reservation,check_in,check_out\n");
247	
248	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
249	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
250	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
251	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
252	            .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
253	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
254	            .collect(Collectors.toList());
255	
256	        for (Reservation reservation : occupiedReservations) {
257	            Room room = roomService.getRoom(reservation.getRoomNumber());
258	            csv.append(reservation.getRoomNumber()).append(",");
259	            csv.append(room.getType()).append(",");
260	            csv.append(reservation.getId()).append(",");
261	            csv.append(formatDateForCsv(reservation.getCheckIn())).append(",");
262	            csv.append(formatDateForCsv(reservation.getCheckOut())).append("\n");
263	        }
264	
265	        int totalRooms = roomService.getAllRooms().size();
266	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms);
267	
268	        return csv.toString();
269	    }
270	
271	    public String generateRevenueReport(YearMonth month) {
272	        StringBuilder csv = new StringBuilder();
273	        csv.append("reservation,room,check_in,check_out,status,amount\n");
274	
275	        LocalDate monthStart = month.atDay(1);
276	        LocalDate monthEnd = month.atEndOfMonth();
277	
278	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
279	            .filter(r -> !r.getCheckIn().isBefore(monthStart) && !r.getCheckIn().isAfter(monthEnd))
280	            .filter(r -> {
281	                BigDecimal netAmount = r.getAmountPaid().subtract(
282	                    r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO
283	                );
284	                return netAmount.compareTo(BigDecimal.ZERO) > 0;
285	            })
286	            .sorted(Comparator.comparing(Reservation::getCheckIn)
287	                             .thenComparing(Reservation::getId))
288	            .collect(Collectors.toList());
289	
290	        BigDecimal total = BigDecimal.ZERO;
291	
292	        for (Reservation reservation : monthReservations) {
293	            BigDecimal netAmount = reservation.getAmountPaid().subtract(
294	                reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO
295	            );
296	
297	            csv.append(reservation.getId()).append(",");
298	            csv.append(reservation.getRoomNumber()).append(",");
299	            csv.append(formatDateForCsv(reservation.getCheckIn())).append(",");
300	            csv.append(formatDateForCsv(reservation.getCheckOut())).append(",");
301	            csv.append(reservation.getStatus()).append(",");
302	            csv.append(formatMoneyForCsv(netAmount)).append("\n");
303	
304	            total = total.add(netAmount);
305	        }
306	
307	        csv.append("total,").append(formatMoneyForCsv(total));
308	
309	        return csv.toString();
310	    }
311	
312	    private String formatDateForCsv(LocalDate date) {
313	        return date.format(DateTimeFormatter.ISO_LOCAL_DATE);
314	    }
315	
316	    private String formatMoneyForCsv(BigDecimal value) {
317	        return String.format("%.2f", value);
318	    }
319	}
